pub fn contains_key(&self, pair_key: &PairKey) -> bool {
    self.contact_graph.contains_key(pair_key)
}

/// Returns an iterator yielding immutable access to all touching contact pairs.
#[inline]
pub fn iter(&self) -> impl Iterator<Item = &ContactPair> {
    self.contact_graph
        .iter_active_touching()
        .chain(self.contact_graph.iter_sleeping_touching())
}

/// Returns an iterator yielding immutable access to all touching contact pairs
/// involving the given entity.
#[inline]
pub fn collisions_with(&self, entity: Entity) -> impl Iterator<Item = &ContactPair> {
    self.contact_graph
        .contact_pairs_with(entity)
        .filter(|contact_pair| contact_pair.is_touching())
}

/// transformed by `translation` and `rotation`.
///
/// The returned tuple is in the format `(distance, normal)`.
///
/// # Arguments
///
/// - `ray_origin`: Where the ray is cast from.
/// - `ray_direction`: What direction the ray is cast in.
/// - `max_distance`: The maximum distance the ray can travel.
/// - `solid`: If true and the ray origin is inside of a collider, the hit point will be the ray origin itself.
///   Otherwise, the collider will be treated as hollow, and the hit point will be at the collider's boundary.
pub fn cast_ray(
    &self,
    translation: impl Into<Position>,
    rotation: impl Into<Rotation>,
    ray_origin: Vector,
    ray_direction: Vector,
    max_distance: Scalar,
    solid: bool,
) -> Option<(Scalar, Vector)> {
    let hit = self.shape_scaled().cast_ray_and_get_normal(
        &make_pose(translation, rotation),
        &parry::query::Ray::new(ray_origin, ray_direction),
        max_distance,
        solid,
    );
    hit.map(|hit| (hit.time_of_impact, hit.normal))
}

